<script lang="ts">
 import {onMount} from 'svelte';import {page} from '$app/stores';import Heading from '$lib/components/Heading.svelte';import Icon from '$lib/components/Icon.svelte';import Explorer from '$lib/components/files/Explorer.svelte';import {workspace,createProject,deploy} from '$lib/stores/workspace';import {slugify} from '$lib/model';import {goto} from '$app/navigation';import {readUploads,snapshotLocal,snapshotSource,stageProject} from '$lib/files/store';import {treeBytes,sizeLabel,type Tree} from '$lib/files/model.js';
 let name='',image='nginx:alpine',domain='',error='',sourceError='',choose=false,picker=false,change=false,busy=false,sourceMode=false;
 let source:null|{tree:Tree,label:string,key:string,path:string}=null;let fileInput:HTMLInputElement,folderInput:HTMLInputElement;
 let directKey='',directPath='';
 onMount(()=>{directKey=$page.url.searchParams.get('source')||'';directPath=$page.url.searchParams.get('path')||'';if(directKey&&directPath){picker=true;try{accept(snapshotSource(directKey,directPath));}catch(e){sourceError=e instanceof Error?e.message:'Source unavailable.';}}});
 function accept(value:NonNullable<typeof source>){source=value;const folder=value.path.split('/').at(-1)||Object.keys(value.tree).find(p=>p.includes('/'))?.split('/')[1]||'application';name=slugify(folder.replace(/\.zip$/i,''))||'application';sourceMode=true;picker=false;sourceError='';}
 async function selectFiles(list:FileList|null){if(!list?.length)return;const selected=Array.from(list);busy=true;choose=false;try{accept(snapshotLocal(await readUploads(selected)));const first=selected[0];name=slugify((first.webkitRelativePath?.split('/')[0]||first.name).replace(/\.[^.]+$/,''))||'application';}catch(e){sourceError=e instanceof Error?e.message:'File selection failed.';}finally{busy=false;fileInput.value='';folderInput.value='';}}
 async function submit(){try{error='';if(sourceMode&&source){const snapshot=source;const id=createProject(name,'',domain,{key:snapshot.key,path:snapshot.path,label:snapshot.label},()=>stageProject(slugify(name),snapshot.tree));await goto('/projects/'+id+'/files');}else{if(!image.trim())throw Error('Enter an image reference.');const id=createProject(name,image,domain);deploy(id,image);await goto('/projects/'+id+'/deployments');}}catch(e){error=e instanceof Error?e.message:'Could not create project.';}}
</script>
<Heading title="New project" subtitle="Choose your application source."/><div class="stack"><section class="card"><div class="section-title"><h3>Upload your application</h3><p class="subtitle">Step 1 of 2 · Add your source files</p></div><div class="upload-drop" on:dragover|preventDefault on:drop|preventDefault={(e)=>selectFiles(e.dataTransfer?.files||null)} role="region" aria-label="Application file drop area"><span class="icon-box"><Icon name="Upload"/></span><h3>Drag and drop your project here</h3><p class="subtitle">Drop a ZIP or source files here, or select them from your computer.</p><div class="upload14-actions"><button class="btn primary" disabled={busy} on:click={()=>choose=!choose}>{busy?'Reading…':'Upload from computer'} <span class="upload14-chevron">⌄</span></button>{#if choose}<div class="upload14-menu"><button on:click={()=>fileInput.click()}><Icon name="File"/>Files or ZIP archive</button><button on:click={()=>folderInput.click()}><Icon name="Projects"/>Project folder</button></div>{/if}</div><input hidden type="file" multiple bind:this={fileInput} on:change={()=>selectFiles(fileInput.files)}/><input hidden type="file" multiple {...{webkitdirectory:''}} bind:this={folderInput} on:change={()=>selectFiles(folderInput.files)}/></div><div class="native-note"><button class="choice native-source-choice" on:click={()=>picker=!picker}><Icon name="Storage"/><span><strong>Use existing files</strong><small>Select a ZIP or project folder from your File Manager.</small></span><Icon name="Arrow"/></button></div>{#if picker}<div class="native-note"><Explorer picker={true} initialKey={directKey} initialPath={directPath} onSelect={accept}/></div>{/if}{#if sourceError}<p class="error" role="alert">{sourceError}</p>{/if}{#if source}<div class="callout native-note native-source-selected"><strong>Source selected</strong><p>{source.label} · {sizeLabel(treeBytes(source.tree))}. A copy will be saved to the new project. Original files remain unchanged.</p><button class="btn secondary small" on:click={()=>{source=null;sourceMode=false;}}>Clear source</button></div>{/if}<p class="subtitle native-note">Sample files only · 1 MiB per batch/source, 500 entries per tree. ZIP extraction and automatic detection are part of the next milestone. No uploaded files are executed.</p></section>
<form class="card stack" style="max-width:850px" on:submit|preventDefault={submit}><div><h3>{sourceMode?'Save application draft':'Deploy a container image'}</h3><p class="subtitle">{sourceMode?'Step 2 of 2 · Store a source copy; inspection and build are pending.':'Milestone 01 preview · no Docker operations performed.'}</p></div><label class="field">Project name<input required bind:value={name} placeholder="my-application"/></label>{#if !sourceMode}<label class="field">Container image<input required bind:value={image} placeholder="nginx:alpine"/><small>Example image reference only.</small></label>{/if}<div class="well"><div class="row between"><span class="strong">Deployment address</span><button class="btn ghost small" type="button" on:click={()=>change=!change}>{change?'Close':'Change'}</button></div><div class="strong native-path">{domain||((slugify(name)||'my-project')+'.drevanta.example')}</div><small>Automatically assigned unless you choose a workspace domain.</small>{#if change}<label class="field native-note">Available address<select bind:value={domain}><option value="">Automatic address</option>{#each $workspace.domains.filter(d=>!d.project) as d}<option value={d.id}>{d.name}</option>{/each}</select></label>{/if}</div>{#if error}<p class="error" role="alert">{error}</p>{/if}<div class="native-actions"><a class="btn secondary" href="/projects">Cancel</a><button class="btn primary" type="submit" disabled={busy}>{sourceMode?'Save project draft':'Simulate deployment'}</button></div></form></div>
